+const { isIdle } = require('./idle');
+
+function sweep(store, now) {
+  const kept = {};
+  for (const [id, session] of Object.entries(store)) {
+    if (!isIdle(session, now)) kept[id] = session;
+  }
+  return kept;
+}
+
+module.exports = { sweep };
